// There is lots of other great polyhedra stuff on Shadertoy. Search for polyhedra, platonic, regular, etc.

/*
These tiny SDFs are inexact and report corners are closer than they are causing more
marching steps, but that might be offset a little by their increased efficiency.
They use lots of symmetries and form a bunch of planes for each
face all insecting at 0, but are then pushed out to create volume.
*/

/*
The inner, mid, and circumscribed spheres all play a role here.
Cube & octahedron share the same inner and circumscribed sphere radii,
as do icosahedron and dodecahedron, and alternating them is the basic animation here.
The midsphere radii are all different, but when they match during animation,
there is some nice complexity and edges of both shapes intersect at right angles.
*/

#define max4(A,B,C,D) max(max(A,B),max(C,D))
#define max3(A,B,C) max(max(A,B),C)

#define twizzle(p) \
    if ( p.y >= max(p.x,p.z) ) p = p.yzx; \
    else if ( p.z >= max(p.x,p.y) ) p = p.zxy;

float sdTetrahedron(vec3 p,float r) {
    twizzle(p) // abs(p) here makes something else nice
    return max3( /*-p.x+p.y+p.z,*/ p.x-p.y+p.z, p.x+p.y-p.z, -p.x-p.y-p.z)/sqrt(3.) - r;
}

float sdCube(vec3 p,float r) {
    p = abs(p); twizzle(p) // so similar that a compiler might generate the same code...
    return p.x - r;
    //return max3(p.x,p.y,p.z) - r;
}

float sdOctahedron(vec3 p,float r) {
    p = abs(p); // twizzle(p) no benifit here
    return (p.x+p.y+p.z)/sqrt(3.) - r;
}

#define PHI 1.6180339887

float sdDodecahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max( /* p.y+p.z*PHI, */ p.z+p.x*PHI, p.x+p.y*PHI )/sqrt(2.+PHI) - r;
}

float sdIcosahedron(vec3 p,float r) {
    p = abs(p); twizzle(p)
    return max3( p.x+p.y+p.z, /* p.y/PHI+p.z*PHI, */ p.z/PHI+p.x*PHI, p.x/PHI+p.y*PHI )/sqrt(3.) - r;
}    

#define ROT2(ANG) mat2(cos(ANG),sin(ANG),-sin(ANG),cos(ANG))

#define PI 3.141592653589793
#define TAU (2.*PI)

vec3 Spin(float tim,vec3 p) {
   tim += iTime;
   p.xz *= ROT2(tim*.75+iMouse.x*TAU/iResolution.x);
   p.yz *= ROT2(tim*.25+iMouse.y*TAU/iResolution.y);
   p.yx *= ROT2(tim*.5);
   return p;
}

#define SEQ(tim,v1,v2,v3,dur) \
mod(tim,dur*8.)<dur*1.?v1: \
mod(tim,dur*8.)<dur*2.?mix(v1,v2,fract(tim/dur)): \
mod(tim,dur*8.)<dur*3.?v2: \
mod(tim,dur*8.)<dur*4.?mix(v2,v3,fract(tim/dur)): \
mod(tim,dur*8.)<dur*5.?v3: \
mod(tim,dur*8.)<dur*6.?mix(v3,v2,fract(tim/dur)): \
mod(tim,dur*8.)<dur*7.?v2: \
  mix(v2,v1,fract(tim/dur))

#define T(SDF) if ( (tmp = SDF) < hit.x ) hit = vec2(tmp,clr); clr += 1.;

// Rodrigues' rotation formula
#define rod(r,n,t) (r * cos(t) + (1. - cos(t)) * dot(r, n) * n + cross(n, r) * sin(t))

vec2 Dist(vec3 pt) {
    vec2 hit = vec2(100000,0);
    float tmp, clr = 0.;

    vec3 p = Spin(0.,pt-vec3(9,0,0));

    //float ss=sin(iTime*.5)*.5; // found empirically
    float ss=SEQ(iTime,.5,.23,-.5,2.);
    T(sdDodecahedron(p,5.-ss))
    vec3 qq = rod( p, normalize(vec3(1)), -PI/4. ); // found empirically
    T(sdIcosahedron(qq,5.+ss))

    p = Spin(0.,pt-vec3(-9,0,0));
    //ss=sin(iTime*.5)*1.; // found empirically
    ss=SEQ(iTime,1.,.29,-1.,2.);
    T(sdCube(p,4.-ss))
    qq = rod(p, normalize(vec3(1)), PI/1.5 ); // found empirically
    T(sdOctahedron(qq,4.+ss))

    T(pt.z+200.);
    return hit;
}


vec4 March(vec3 beg,vec3 dir) {
    float dist = 0.;
    vec3 pos;
    #define LIMIT 100
    for ( int stps = 0; stps <= LIMIT; ++stps ) {
        pos = beg + dir * dist;
        vec2 obj = Dist( pos );
        dist += obj.x;
        if ( obj.x < .001 || stps == LIMIT ) return vec4( pos, obj.y );
    }
    return vec4( pos, 90. );
}

vec3 Normal(vec3 pt) {
    float delta = .001;
    vec3 norm = Dist(pt).x - vec3(
        Dist(pt-vec3(delta, 0., 0.)).x, 
        Dist(pt-vec3( 0.,delta, 0.)).x, 
        Dist(pt-vec3( 0., 0.,delta)).x );
    return normalize( norm );
}

float pow2n(float i,int n)
{
  while ( n-- > 0 ) i *= i;
  return i;
}

void mainImage( out vec4 O, vec2 U )
{

    vec2 R = iResolution.xy;
    vec2 uv = (U+U-R) / min(R.x,R.y);  // -1 ... +1
    uv /= 5.;

    vec3 cam = vec3( 0, 0, -64.);
    vec3 camdir = normalize( vec3( uv, 1. ) );

    vec4 hit = March( cam, camdir );
    vec3 norm = Normal(hit.xyz);

    vec3 light = vec3( 10.+5.*sin(iTime*4.), 10.+5.*cos(iTime*4.), -10 );
    vec3 dir = normalize( light - hit.xyz );
    float difu = dot( norm, dir );

    difu = .5 + .5*difu;

    #define col4(X) ( .5 + .3 * sin( vec4(0,21,23,0) + (X) ) )
    O = col4(hit.w*.4);
    O *= difu + pow2n(difu,9);
    O = sqrt( O );
}
